param([Parameter(Mandatory)][string]$InputPath,[Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop'
$data=Get-Content -LiteralPath $InputPath -Raw|ConvertFrom-Json
function Stats($values){$sorted=@($values|Sort-Object);$n=$sorted.Count;if(-not $n){return $null};$median=if($n%2){$sorted[[int][math]::Floor($n/2)]}else{($sorted[$n/2-1]+$sorted[$n/2])/2};return [ordered]@{n=$n;min=$sorted[0];median=$median;p90=$sorted[[int][math]::Ceiling(.9*$n)-1];p95=$sorted[[int][math]::Ceiling(.95*$n)-1];max=$sorted[-1]}}
$summaries=@();$gaps=@();$orders=@()
foreach($group in ($data.runs|Group-Object Policy,Scenario)){
    $runs=@($group.Group);$milestones=[ordered]@{}
    foreach($name in @('first-repair','workshop','era-ready','chapter-end','all-skills-owned')){$milestones[$name]=[ordered]@{spins=(Stats @($runs|ForEach-Object {$_.Milestones.$name.Spins}));nominalAutoEligibleSeconds=(Stats @($runs|ForEach-Object {$_.Milestones.$name.NominalAutoSeconds}));manualFloorSeconds=(Stats @($runs|ForEach-Object {$_.Milestones.$name.ManualSeconds}));decisionsPlus2Seconds=(Stats @($runs|ForEach-Object {$_.Milestones.$name.AutoPlusTwoSecondsPerDecision}))}}
    $summaries+=[ordered]@{policy=$runs[0].Policy;scenario=$runs[0].Scenario;milestones=$milestones;longestConstructionGap=(Stats @($runs|ForEach-Object LongestConstructionGapNominalAutoSeconds));skillsAtChapterEnd=(Stats @($runs|ForEach-Object SkillsOwnedAtChapterEnd))}
    foreach($run in $runs){$last=0;foreach($event in ($run.Purchases|Where-Object Kind -eq 'construction')){$gaps+=[pscustomobject]@{policy=$run.Policy;scenario=$run.Scenario;seed=$run.Seed;project=$event.Id;seconds=$event.NominalAutoSeconds-$last};$last=$event.NominalAutoSeconds}}
    if($runs[0].Scenario -eq 'continuous'){foreach($id in @('order.sort-salvage','order.neighborhood-supply')){$seedTotals=@($runs|ForEach-Object {$r=@($_.Orders|Where-Object Id -eq $id);$seconds=($r|Measure-Object NominalManualSeconds -Sum).Sum;$rewards=($r|Measure-Object ClaimIncome -Sum).Sum;[pscustomobject]@{spins=($r|Measure-Object Spins -Sum).Sum;seconds=$seconds;rewards=$rewards;claimCoinsPerMinute=$rewards*60/$seconds;instances=$r.Count}});$orders+=[ordered]@{policy=$runs[0].Policy;id=$id;seedSamples=$runs.Count;instancesPerSeed=$seedTotals[0].instances;threeInstanceSpins=(Stats @($seedTotals|ForEach-Object spins));threeInstanceManualSeconds=(Stats @($seedTotals|ForEach-Object seconds));extraClaimCoinsPerNominalMinute=(Stats @($seedTotals|ForEach-Object claimCoinsPerMinute))}}}
}
$gapSummary=@($gaps|Group-Object policy,scenario,project|ForEach-Object {$r=@($_.Group);[pscustomobject]@{policy=$r[0].policy;scenario=$r[0].scenario;project=$r[0].project;seconds=(Stats @($r|ForEach-Object seconds))}})
$pairs=@();foreach($a in ($data.runs|Where-Object {$_.Policy -eq 'construction-first'})){$b=$data.runs|Where-Object {$_.Policy -eq 'affordable-skills-first' -and $_.Scenario -eq $a.Scenario -and $_.Seed -eq $a.Seed};if($b){$pairs+=[ordered]@{scenario=$a.Scenario;seed=$a.Seed;chapterSpinSaving=$a.Milestones.'chapter-end'.Spins-$b.Milestones.'chapter-end'.Spins;allSkillSpinSaving=$a.Spins-$b.Spins;eraReadyDelay=$b.Milestones.'era-ready'.Spins-$a.Milestones.'era-ready'.Spins;longestGapSavingSeconds=$a.LongestConstructionGapNominalAutoSeconds-$b.LongestConstructionGapNominalAutoSeconds}}}
$offline=@();foreach($r in ($data.runs|Where-Object Scenario -ne 'continuous')){$b=$data.runs|Where-Object {$_.Policy -eq $r.Policy -and $_.Scenario -eq 'continuous' -and $_.Seed -eq $r.Seed};$offline+=[ordered]@{policy=$r.Policy;seed=$r.Seed;offlineCoins=$r.OfflineIncome;foregroundSpinsSaved=$b.Milestones.'chapter-end'.Spins-$r.Milestones.'chapter-end'.Spins;extraWallSeconds=$r.AbsenceSeconds+$r.Milestones.'chapter-end'.NominalAutoSeconds-$b.Milestones.'chapter-end'.NominalAutoSeconds}}
[ordered]@{inputSha256=(Get-FileHash -LiteralPath $InputPath -Algorithm SHA256).Hash;summaries=$summaries;gapsByProject=$gapSummary;postchapterOrders=$orders;pairedPolicies=$pairs;offlinePairs=$offline}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $OutputPath
Write-Output $OutputPath
